function Check-Budget([int] $Reserve = 0) {
    $CancellationToken.ThrowIfCancellationRequested()
    if ($clock.Elapsed.TotalSeconds -ge ($maximumSeconds - $Reserve)) { throw 'Native production orchestration deadline expired.' }
}
